export const TRAIT_SECTIONS = ['统帅', '文明', '军事', '地理']

export function traitsOf(name) {
  return TRAITS_BY_COUNTRY[name] || null
}

export function traitPoints(name) {
  const card = TRAITS_BY_COUNTRY[name]
  if (!card) return 0
  return card.traits.reduce((n, t) => n + (Number(t.points) || 0), 0)
}


